style.css:
@-moz-document domain("docs.52im.net") {
.g_talkwith_siteowner {
    display: none;
  }

  .Part > h1, .Sect > h4 {
    font-family: 方正黑体简体, 苹方-简, 微软雅黑, "Noto Sans CJK SC", sans-serif;
  }

  .Sect > p {
    font-family: 方正新书宋简体, 宋体-简, 华文宋体, 新宋体, "Noto Serif CJK SC", serif;
    text-indent: unset !important;
  }

  .net52im_p_quote, .net52im_ol, .net52im_ol_none {
    font-family: 方正楷体简体, 华文楷体, 楷体, "Noto Serif CJK SC", serif;
  }

  .net52im_p_quote {
    margin-left: 0px;
  }

  .net52im_ol {
    font-size: 13px;
  }

  .net52im_ol li, .net52im_ol_none li {
    margin-top: 0.5em;
  }
}
